1408	func (s *Store) persist(st *persistedState) error {
1409		data, err := json.MarshalIndent(st, "", "  ")
1410		if err != nil {
1411			return err
1412		}
1413		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
