1415		if err != nil {
1416			return err
1417		}
1418		if _, err := f.Write(data); err != nil {
1419			f.Close()
1420			return err
1421		}
1422		if err := f.Sync(); err != nil {
1423			f.Close()
1424			return err
1425		}
1426		if err := f.Close(); err != nil {
1427			return err
1428		}
