1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"strings"
11		"testing"
12	)
13	
14	// 本文件是“已保存的成功创建批次请求的返回结果必须对应原提交内容第一次创建
15	// 成功时的内容”的回归保障：批次用请求编号创建后，按原编号、原内容再次提交
16	// CreateBatch，只能取回第一次创建时的结果（原选配方版本与份数、草稿状态、
17	// 空投料、实投为零、差额为应投量的负值）。台账里保存的创建结果即使变成
18	// null、空对象，或被改成另一批次的结果、被改掉配方绑定/份数/状态，或混入
19	// 了批次后来的调整、投料与关闭现状，也不能被当作成功结果返回——打开台账及
20	// 之后的每次查询/写入重载，都必须核对保存结果与原提交内容（原请求对应的
21	// 批次与原选配方版本必须仍然存在）一致；不一致按 ErrCorruptData 拒绝整份
22	// 台账，不删除请求、不补造批次，也不用当前查询结果覆盖损坏结果。
23	
24	// setupCreateRequestLedger 在 dir 建立一份正常台账：
25	//   - B1（已关闭）：由 create-b1 用 R1/v1、8 份创建，随后草稿调整为 R1/v2、
26	//     3 份，开始执行、登记两条投料（f1、f2）并关闭——其保存的创建结果必须
27	//     仍是首次创建时的内容（R1/v1、8 份、草稿、空投料），不能混入后来的
28	//     调整、投料与关闭现状；
29	//   - B2（草稿）：用 R1/v2、3 份创建——其创建结果与 B1 的当前计划内容相同，
30	//     但那是另一批次的创建结果，用于验证不能顶替；
31	//   - B3（草稿）：R1/v2、2 份的正常批次，用于验证损坏的创建请求不能被
32	//     “本次访问的是另一个正常批次”绕过。
33	//
34	// 返回落盘后的台账文件内容，供各用例改坏后重写。
35	func setupCreateRequestLedger(t *testing.T, dir string) []byte {
36		t.Helper()
37		s, err := Open(dir)
38		if err != nil {
39			t.Fatalf("Open 失败: %v", err)
40		}
41		registerCreateReplayRecipes(t, s) // R1/v1：M1=0.125、M2=0.001；R1/v2：M1=250、M4=2
42		if _, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8); err != nil {
43			t.Fatal(err)
44		}
45		if _, err := s.UpdateDraftBatch("u-final", "B1", "R1", "v2", 3); err != nil {
46			t.Fatal(err)
47		}
48		if _, err := s.StartBatch("start-b1", "B1"); err != nil {
49			t.Fatal(err)
50		}
51		base := replayFeedTime()
52		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", base, "张三"); err != nil {
53			t.Fatal(err)
54		}
55		if _, err := s.AddFeeding("f2", "B1", "M4", "2", base, "李四"); err != nil {
56			t.Fatal(err)
57		}
58		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
59			t.Fatal(err)
60		}
61		// B2：配方与份数和 B1 的当前计划相同，仅批次编号与请求编号不同。
62		if _, err := s.CreateBatch("create-b2", "B2", "R1", "v2", 3); err != nil {
63			t.Fatal(err)
64		}
65		// B3：正常批次，不参与任何改坏。
66		if _, err := s.CreateBatch("create-b3", "B3", "R1", "v2", 2); err != nil {
67			t.Fatal(err)
68		}
69		if err := s.Close(); err != nil {
70			t.Fatal(err)
71		}
72		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
73		if err != nil {
74			t.Fatal(err)
75		}
76		return good
77	}
78	
79	// createResultRaw 取出正常台账中 reqNo 请求的保存结果原文。
80	func createResultRaw(t *testing.T, good []byte, reqNo string) json.RawMessage {
81		t.Helper()
82		var st persistedState
83		if err := json.Unmarshal(good, &st); err != nil {
84			t.Fatal(err)
85		}
86		req := st.Requests[reqNo]
87		if req == nil {
88			t.Fatalf("正常台账中应存在 %s 请求记录", reqNo)
89		}
90		return req.Result
91	}
92	
93	// mutatedCreateView 读出 create-b1 的保存结果，按 edit 修改后重新序列化。
94	func mutatedCreateView(t *testing.T, good []byte, edit func(*BatchView)) json.RawMessage {
95		t.Helper()
96		var v BatchView
97		if err := json.Unmarshal(createResultRaw(t, good, "create-b1"), &v); err != nil {
98			t.Fatal(err)
99		}
100		edit(&v)
101		raw, err := json.Marshal(v)
102		if err != nil {
103			t.Fatal(err)
104		}
105		return raw
106	}
107	
108	// corruptCreateRequestResult 把正常台账内容中 create-b1 请求的保存结果替换为
109	// mutate 给出的值（mutate 返回 nil 表示删除该字段），返回改写后的文件内容。
110	func corruptCreateRequestResult(t *testing.T, good []byte, mutate func() json.RawMessage) []byte {
111		t.Helper()
112		var st persistedState
113		if err := json.Unmarshal(good, &st); err != nil {
114			t.Fatal(err)
115		}
116		req := st.Requests["create-b1"]
117		if req == nil {
118			t.Fatalf("正常台账中应存在 create-b1 请求记录")
119		}
120		req.Result = mutate()
121		data, err := json.MarshalIndent(&st, "", "  ")
122		if err != nil {
123			t.Fatal(err)
124		}
125		return data
126	}
127	
128	// 已保存的成功创建批次请求的结果缺失、为 null、为空对象、无法读成批次结果，
129	// 或与原提交内容第一次创建成功时的内容不一致（批次编号、配方绑定、计划份数、
130	// 状态、投料列表、逐物料应投量/实投量/差额有任何差异，含被另一批次的结果
131	// 顶替、混入后来的调整、投料或关闭现状）时，Open 必须返回 ErrCorruptData：
132	// 错误信息指出问题请求编号及关联批次，不返回可用的台账对象，也不改写原文件。
133	func TestOpenRejectsCorruptCreateRequestResult(t *testing.T) {
134		cases := []struct {
135			name   string
136			mutate func(good []byte) json.RawMessage
137		}{
138			{"结果缺失", func(good []byte) json.RawMessage { return nil }},
139			{"结果为 null", func(good []byte) json.RawMessage { return json.RawMessage("null") }},
140			{"结果为空对象", func(good []byte) json.RawMessage { return json.RawMessage(`{}`) }},
141			{"结果不是批次结果对象", func(good []byte) json.RawMessage { return json.RawMessage(`"not-an-object"`) }},
142			{"结果被替换成另一批次的创建结果", func(good []byte) json.RawMessage {
143				// B2 的配方、份数与 B1 的当前计划相同，但那是另一批次的创建结果。
144				return createResultRaw(t, good, "create-b2")
145			}},
146			{"结果批次编号被改成另一批次", func(good []byte) json.RawMessage {
147				return mutatedCreateView(t, good, func(v *BatchView) { v.BatchNo = "B2" })
148			}},
149			{"结果配方编号被改", func(good []byte) json.RawMessage {
150				return mutatedCreateView(t, good, func(v *BatchView) { v.RecipeNo = "RX" })
151			}},
152			{"结果沿用后来调整的版本", func(good []byte) json.RawMessage {
153				return mutatedCreateView(t, good, func(v *BatchView) { v.RecipeVersion = "v2" })
154			}},
155			{"结果配方名称被改", func(good []byte) json.RawMessage {
156				return mutatedCreateView(t, good, func(v *BatchView) { v.RecipeName = "被改的名称" })
157			}},
158			{"结果沿用后来调整的份数", func(good []byte) json.RawMessage {
159				return mutatedCreateView(t, good, func(v *BatchView) { v.PlannedPortions = 3 })
160			}},
161			{"结果状态被改成关闭后的现状", func(good []byte) json.RawMessage {
162				return mutatedCreateView(t, good, func(v *BatchView) { v.Status = StatusClosed })
163			}},
164			{"结果混入了后来追加的投料", func(good []byte) json.RawMessage {
165				return mutatedCreateView(t, good, func(v *BatchView) {
166					base := replayFeedTime()
167					v.Feedings = []FeedingView{
168						{Seq: 1, MaterialNo: "M1", Grams: "100.5", Time: base, Registrar: "张三"},
169						{Seq: 2, MaterialNo: "M4", Grams: "2", Time: base, Registrar: "李四"},
170					}
171				})
172			}},
173			{"物料核对项少一项", func(good []byte) json.RawMessage {
174				return mutatedCreateView(t, good, func(v *BatchView) {
175					v.Materials = v.Materials[:1]
176				})
177			}},
178			{"物料核对项混入后来版本的物料", func(good []byte) json.RawMessage {
179				return mutatedCreateView(t, good, func(v *BatchView) {
180					v.Materials = append(v.Materials, MaterialRequirement{
181						MaterialNo: "M4", RequiredGrams: "6", ActualGrams: "0", DifferenceGrams: "-6",
182					})
183				})
184			}},
185			{"物料核对顺序被调换", func(good []byte) json.RawMessage {
186				return mutatedCreateView(t, good, func(v *BatchView) {
